def test_len2_k2(run, x):
    s, ks = x.split()
    limit, k = int(s, 2), int(ks)
    def operations(v):
        total = 0
        while v != 1:
            v = bin(v).count('1')
            total += 1
        return total
    expected = sum(operations(v) == k for v in range(1, limit + 1))
    assert int(run(x).strip()) == expected


def test_len3_k3(run, x):
    s, ks = x.split()
    limit, k = int(s, 2), int(ks)
    def operations(v):
        steps = 0
        while v != 1:
            v = v.bit_count()
            steps += 1
        return steps
    expected = sum(1 for v in range(1, limit + 1) if operations(v) == k)
    assert int(run(x).strip()) == expected


def test_len4_k2(run, x):
    s, ks = x.split()
    limit, k = int(s, 2), int(ks)
    expected = 0
    for value in range(1, limit + 1):
        current = value
        steps = 0
        while current > 1:
            current = bin(current).count('1')
            steps += 1
        if steps == k:
            expected += 1
    assert int(run(x).strip()) == expected


def test_len5_k3(run, x):
    s, ks = x.split()
    limit, k = int(s, 2), int(ks)
    def special(value):
        count = 0
        while value != 1:
            value = value.bit_count()
            count += 1
        return count == k
    expected = sum(special(value) for value in range(1, limit + 1))
    assert int(run(x).strip()) == expected


def test_len6_k3(run, x):
    bits, text_k = x.split()
    n, k = int(bits, 2), int(text_k)
    expected = 0
    for candidate in range(1, n + 1):
        depth = 0
        while candidate != 1:
            candidate = candidate.bit_count()
            depth += 1
        expected += depth == k
    assert int(run(x).strip()) == expected


def test_len7_k4(run, x):
    s, ks = x.split()
    upper, k = int(s, 2), int(ks)
    depths = []
    for value in range(1, upper + 1):
        depth = 0
        reduced = value
        while reduced != 1:
            reduced = bin(reduced)[2:].count('1')
            depth += 1
        depths.append(depth)
    assert int(run(x).strip()) == sum(depth == k for depth in depths)


def test_len8_k2(run, x):
    s, ks = x.split()
    upper, k = int(s, 2), int(ks)
    expected = 0
    for value in range(1, upper + 1):
        reduced = value
        operations = 0
        while reduced != 1:
            reduced = reduced.bit_count()
            operations += 1
        if operations == k:
            expected += 1
    assert int(run(x).strip()) == expected


def test_len9_k3(run, x):
    s, ks = x.split()
    upper, k = int(s, 2), int(ks)
    def depth(value):
        if value == 1:
            return 0
        return 1 + depth(value.bit_count())
    expected = sum(depth(value) == k for value in range(1, upper + 1))
    assert int(run(x).strip()) == expected


def test_len10_k3(run, x):
    binary_n, k_text = x.split()
    upper, k = int(binary_n, 2), int(k_text)
    expected = 0
    for value in range(1, upper + 1):
        chain = [value]
        while chain[-1] != 1:
            chain.append(chain[-1].bit_count())
        if len(chain) - 1 == k:
            expected += 1
    assert int(run(x).strip()) == expected


def test_len11_k4(run, x):
    s, ks = x.split()
    upper, wanted = int(s, 2), int(ks)
    expected = 0
    for value in range(1, upper + 1):
        steps = 0
        reduced = value
        while reduced != 1:
            ones = 0
            probe = reduced
            while probe:
                ones += probe & 1
                probe //= 2
            reduced = ones
            steps += 1
        if steps == wanted:
            expected += 1
    assert int(run(x).strip()) == expected

