tests_src:
def test_no_round(run, x):
    out = run(x).strip()
    if x == '3 1\n1.2\n':
        assert out == '1.2'
    else:
        assert out == out

def test_integer_tie(run, x):
    out = run(x).strip()
    if x == '3 1\n1.5\n':
        assert out == '2'
    else:
        assert out == out

def test_one_decimal(run, x):
    out = run(x).strip()
    if x == '4 1\n1.45\n':
        assert out == '1.5'
    else:
        assert out == out

def test_two_steps(run, x):
    out = run(x).strip()
    if x == '4 2\n1.45\n':
        assert out == '2'
    else:
        assert out == out

def test_chain_two(run, x):
    out = run(x).strip()
    if x == '5 2\n1.445\n':
        assert out == '1.5'
    else:
        assert out == out

def test_chain_three(run, x):
    out = run(x).strip()
    if x == '6 3\n1.4445\n':
        assert out == '1.5'
    else:
        assert out == out

def test_integer_carry(run, x):
    out = run(x).strip()
    if x == '5 2\n99.45\n':
        assert out == '100'
    else:
        assert out == out

def test_all_nines(run, x):
    out = run(x).strip()
    if x == '5 1\n999.5\n':
        assert out == '1000'
    else:
        assert out == out

def test_late_five(run, x):
    out = run(x).strip()
    if x == '6 1\n1.2345\n':
        assert out == '1.235'
    else:
        assert out == out

def test_late_chain(run, x):
    out = run(x).strip()
    if x == '6 2\n1.2445\n':
        assert out == '1.25'
    else:
        assert out == out

