def test_single_positive(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        total = 0
        for i, v in enumerate(a, 1):
            if not any((mask >> (d - 1)) & 1 and i % d == 0 for d in range(1, n + 1)):
                total += v
        best = max(best, total)
    assert out == best

def test_single_zero(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        total = sum(v for i, v in enumerate(a, 1) if not any((mask >> (d - 1)) & 1 and i % d == 0 for d in range(1, n + 1)))
        best = max(best, total)
    assert out == best

def test_single_negative(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        total = 0
        for i in range(1, n + 1):
            smashed = any((mask >> (d - 1)) & 1 and i % d == 0 for d in range(1, n + 1))
            if not smashed:
                total += a[i - 1]
        best = max(best, total)
    assert out == best

def test_two_divisibility(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        total = 0
        for i, v in enumerate(a, 1):
            for d in range(1, n + 1):
                if ((mask >> (d - 1)) & 1) and i % d == 0:
                    break
            else:
                total += v
        best = max(best, total)
    assert out == best

def test_three_mixed(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    values = []
    for mask in range(1 << n):
        kept = [v for i, v in enumerate(a, 1) if all(not ((mask >> (d - 1)) & 1 and i % d == 0) for d in range(1, n + 1))]
        values.append(sum(kept))
    assert out == max(values)

def test_chain(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        total = sum(a[i - 1] for i in range(1, n + 1) if all(not ((mask >> (d - 1)) & 1 and i % d == 0) for d in range(1, n + 1)))
        if total > best:
            best = total
    assert out == best

def test_zero_mixed(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        total = 0
        for i, v in enumerate(a, 1):
            smashed = False
            for d in range(1, n + 1):
                smashed |= bool((mask >> (d - 1)) & 1 and i % d == 0)
            if not smashed:
                total += v
        best = max(best, total)
    assert out == best

def test_seven_mixed(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for chosen in range(1 << n):
        total = 0
        for label, value in enumerate(a, 1):
            if not any(chosen & (1 << (op - 1)) and label % op == 0 for op in range(1, n + 1)):
                total += value
        best = max(best, total)
    assert out == best

def test_operation_sets(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    best = -10**30
    for mask in range(1 << n):
        smashed = set()
        for d in range(1, n + 1):
            if mask & (1 << (d - 1)):
                smashed.update(range(d, n + 1, d))
        best = max(best, sum(v for i, v in enumerate(a, 1) if i not in smashed))
    assert out == best

def test_all_cases(run, x):
    out = int(run(x).strip())
    p = x.split()
    n = int(p[0]); a = list(map(int, p[1:]))
    if n > 8:
        return
    scores = []
    for mask in range(1 << n):
        score = 0
        for label in range(1, n + 1):
            hit = False
            for op in range(1, n + 1):
                if mask & (1 << (op - 1)) and label % op == 0:
                    hit = True
            if not hit:
                score += a[label - 1]
        scores.append(score)
    assert out == max(scores)

