def test_full_vector(run, x):
    v=list(map(int,x.split())); n=v[0]; g=[v[1:1+n]]+[[q] for q in v[1+n:]]
    for i in range(1,n):
        for j in range(1,n): g[i].append(next(k for k in range(3) if k not in (g[i-1][j],g[i][j-1])))
    want=[sum(q==k for r in g for q in r) for k in range(3)]
    got=list(map(int,run(x).split()))
    assert got==want

