def test_prefix_dp(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    dp = [0] + [10**18] * n
    for end in range(1, n + 1):
        dp[end] = dp[end - 1] + a
        for start in range(end):
            if s[start:end] in s[:start]:
                dp[end] = min(dp[end], dp[start] + b)
    assert run(x).strip() == str(dp[n])

def test_recursive_segments(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    memo = {}
    def solve(pos):
        if pos == n:
            return 0
        if pos in memo:
            return memo[pos]
        best = a + solve(pos + 1)
        for end in range(pos + 1, n + 1):
            if s[pos:end] in s[:pos]:
                best = min(best, b + solve(end))
        memo[pos] = best
        return best
    assert run(x).strip() == str(solve(0))

def test_backward_dp(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    cost = [0] + [10**18] * n
    for i in range(n):
        cost[i + 1] = min(cost[i + 1], cost[i] + a)
        for j in range(i + 1, n + 1):
            if s[i:j] in s[:i]:
                cost[j] = min(cost[j], cost[i] + b)
    assert run(x).strip() == str(cost[-1])

def test_partition_search(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    best = [10**18]
    def visit(pos, spent):
        if spent >= best[0]:
            return
        if pos == n:
            best[0] = spent
            return
        visit(pos + 1, spent + a)
        for end in range(pos + 1, n + 1):
            if s[pos:end] in s[:pos]:
                visit(end, spent + b)
    visit(0, 0)
    assert run(x).strip() == str(best[0])

def test_edge_relaxation(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    dist = [None] * (n + 1)
    dist[0] = 0
    for p in range(n):
        candidates = [(p + 1, a)]
        for q in range(p + 1, n + 1):
            if s[p:q] in s[:p]:
                candidates.append((q, b))
        for q, w in candidates:
            value = dist[p] + w
            if dist[q] is None or value < dist[q]:
                dist[q] = value
    assert run(x).strip() == str(dist[n])

def test_all_cuts(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    answer = [0] * (n + 1)
    for end in range(1, n + 1):
        options = [answer[end - 1] + a]
        for cut in range(end):
            piece = s[cut:end]
            if piece in s[:cut]:
                options.append(answer[cut] + b)
        answer[end] = min(options)
    assert run(x).strip() == str(answer[n])

def test_suffix_choices(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    minimum = [10**18] * (n + 1)
    minimum[0] = 0
    for length in range(1, n + 1):
        minimum[length] = minimum[length - 1] + a
        for prior_end in range(length):
            if s[prior_end:length] in s[:prior_end]:
                candidate = minimum[prior_end] + b
                if candidate < minimum[length]:
                    minimum[length] = candidate
    assert run(x).strip() == str(minimum[n])

def test_memo_search(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    cache = [None] * (n + 1)
    def f(i):
        if i == n:
            return 0
        if cache[i] is not None:
            return cache[i]
        value = a + f(i + 1)
        for size in range(1, n - i + 1):
            if s[i:i + size] in s[:i]:
                value = min(value, b + f(i + size))
        cache[i] = value
        return value
    assert run(x).strip() == str(f(0))

def test_reference_legality(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    d = {0: 0}
    for i in range(n):
        literal = d[i] + a
        d[i + 1] = min(d.get(i + 1, literal), literal)
        for j in range(i + 1, n + 1):
            if s[i:j] in s[:i]:
                candidate = d[i] + b
                d[j] = min(d.get(j, candidate), candidate)
    assert run(x).strip() == str(d[n])

def test_cost_minimum(run, x):
    first, s = x.strip().splitlines()
    n, a, b = map(int, first.split())
    values = [0]
    for end in range(1, n + 1):
        value = values[end - 1] + a
        for begin in range(end):
            earlier = s[:begin]
            token = s[begin:end]
            if earlier.find(token) != -1:
                value = min(value, values[begin] + b)
        values.append(value)
    assert run(x).strip() == str(values[n])

