def test_two_nodes(run, x):
    n = int(x.split()[0])
    out = run(x).strip()
    if n == 2:
        assert out == 'NO'

def test_small_exhaustive(run, x):
    import itertools
    data = list(map(int, x.split()))
    n, c = data[0], data[1:]
    out = run(x).strip()
    if n > 7:
        return
    if n == 1:
        expected = (c == [1])
    else:
        expected = False
        for root in range(n):
            if c[root] != n:
                continue
            for code in itertools.product(range(n), repeat=n - 2):
                deg = [1] * n
                for v in code:
                    deg[v] += 1
                adj = [[] for _ in range(n)]
                code = list(code)
                for v in code:
                    leaf = next(i for i in range(n) if deg[i] == 1)
                    adj[leaf].append(v); adj[v].append(leaf)
                    deg[leaf] -= 1; deg[v] -= 1
                ends = [i for i in range(n) if deg[i] == 1]
                adj[ends[0]].append(ends[1]); adj[ends[1]].append(ends[0])
                def dfs(v, p):
                    sizes = []
                    total = 1
                    for w in adj[v]:
                        if w != p:
                            sizes.append(dfs(w, v)); total += sizes[-1]
                    if sizes and len(sizes) < 2:
                        return -100
                    return total if total == c[v] else -100
                if dfs(root, -1) == n:
                    expected = True
                    break
            if expected:
                break
    assert out == ('YES' if expected else 'NO')

def test_two_threes_witness(run, x):
    data = list(map(int, x.split()))
    n, c = data[0], data[1:]
    out = run(x).strip()
    if n == 8 and sorted(c) == [1, 1, 1, 1, 1, 3, 3, 8]:
