def test_star_witness(run, x):
    data = list(map(int, x.split()))
    n, c = data[0], data[1:]
    out = run(x).strip()
    if (n == 1 and c == [1]) or (n >= 3 and sorted(c) == [1] * (n - 1) + [n]):
