def test_exhaustive_switches(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    controls = [set(map(int, lines[i + 2].split()[1:])) for i in range(m)]
    ok = any(all((a[r] ^ (sum((mask >> s) & 1 for s in range(m) if r + 1 in controls[s]) & 1)) == 1 for r in range(n)) for mask in range(1 << m))
    answer = run(x).strip()
    assert answer == ('YES' if ok else 'NO')

def test_shared_pair_conflict(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    pairs = [[] for _ in range(n)]
    for s in range(m):
        for room in map(int, lines[s + 2].split()[1:]):
            pairs[room - 1].append(s)
    seen = {}
    bad = False
    for room in range(n):
        key = tuple(pairs[room])
        if key in seen and seen[key] != a[room]: bad = True
        seen[key] = a[room]
    answer = run(x).strip()
    assert answer == ('NO' if bad else answer)

def test_target_parity_conflict(run, x):
    lines = x.splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    who = [[] for _ in range(n)]
    for s in range(m):
        for v in map(int, lines[s + 2].split()[1:]): who[v - 1].append(s)
    need = {}
    impossible = False
    for i in range(n):
        k = tuple(who[i])
        if k in need and need[k] != (1 ^ a[i]): impossible = True
        need[k] = 1 ^ a[i]
    answer = run(x).strip()
