def test_empty(run, x):
    out = run(x).strip()
    if x == "1 1\n.\n":
        assert int(out) == 0
    else:
        assert isinstance(int(out), int)

def test_single_black(run, x):
    out = run(x).strip()
    if x == "1 1\n#\n":
        assert int(out) == 1
    else:
        assert isinstance(int(out), int)

def test_empty_row(run, x):
    out = run(x).strip()
    if x == "2 1\n#\n.\n":
        assert int(out) == -1
    else:
        assert isinstance(int(out), int)

def test_empty_column(run, x):
    out = run(x).strip()
    if x == "1 2\n#.\n":
        assert int(out) == -1
    else:
        assert isinstance(int(out), int)

def test_isolated_corner(run, x):
    out = run(x).strip()
    if x == "3 3\n#..\n...\n...\n":
        assert int(out) == 1
    else:
        assert isinstance(int(out), int)

def test_split_row(run, x):
    out = run(x).strip()
    if x == "2 3\n#.#\n###\n":
        assert int(out) == -1
    else:
        assert isinstance(int(out), int)

def test_two_components(run, x):
    out = run(x).strip()
    if x == "3 3\n###\n.#.\n###\n":
        assert int(out) == 2
    else:
        assert isinstance(int(out), int)

def test_diagonal(run, x):
    out = run(x).strip()
    if x == "2 2\n#.\n.#\n":
        assert int(out) == 2
    else:
        assert isinstance(int(out), int)

def test_connected_shape(run, x):
    out = run(x).strip()
    if x == "3 3\n.##\n###\n##.\n":
        assert int(out) == 1
    else:
        assert isinstance(int(out), int)

def test_single_row(run, x):
    out = run(x).strip()
    if x == "1 5\n#####\n":
        assert int(out) == 1
    else:
        assert isinstance(int(out), int)

