def test_definition_oracle(run, x):
    rows = x.split()
    n = int(rows[0])
    a = list(map(int, rows[1:]))
    if n > 8:
        return
    best = None
    for l in range(n):
        total = 0
        for r in range(l + 1, n):
            total += abs(a[r - 1] - a[r]) * (1 if (r - 1 - l) % 2 == 0 else -1)
            best = total if best is None or total > best else best
    assert int(run(x).strip()) == best

def test_all_starts(run, x):
    p = list(map(int, x.split()))
    n, a = p[0], p[1:]
    if n > 8:
        return
    best = -10**30
    for l in range(n - 1):
        s = 0
        sign = 1
        for j in range(l, n - 1):
            s += sign * abs(a[j] - a[j + 1])
            best = max(best, s)
            sign = -sign
    assert int(run(x).strip()) == best

def test_all_ends(run, x):
    q = list(map(int, x.split()))
    n, a = q[0], q[1:]
    if n > 8:
