    values = []
    for r in range(1, n):
        for l in range(r):
            values.append(sum(abs(a[i] - a[i + 1]) * (1 if (i - l) % 2 == 0 else -1) for i in range(l, r)))
    assert int(run(x).strip()) == max(values)

def test_single_edge(run, x):
    z = list(map(int, x.split()))
    n, a = z[0], z[1:]
    if n > 8:
        return
    best = max(abs(a[i] - a[i + 1]) for i in range(n - 1))
    for l in range(n):
        for r in range(l + 2, n + 1):
            v = sum(((-1) ** (i - l)) * abs(a[i] - a[i + 1]) for i in range(l, r - 1))
            best = max(best, v)
    assert int(run(x).strip()) == best

