def test_integer_range(run, x):
    n = int(x.split()[0])
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    assert 1 <= v <= n

def test_keep_original(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    best = 0
    for m in range(1 << len(a)):
        q = [a[i] for i in range(len(a)) if m >> i & 1]
        if all(q[i] <= q[i+1] for i in range(len(q)-1)):
            best = max(best, len(q))
    assert v >= best

def test_keep_equal_values(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    assert v >= max(a.count(1), a.count(2))

def test_keep_nondecreasing_run(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    best = cur = 1
    for i in range(1, len(a)):
        cur = cur + 1 if a[i-1] <= a[i] else 1
        best = max(best, cur)
    assert v >= best

def test_sortable_reversal(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    possible = False
    for l in range(len(a)):
        for r in range(l, len(a)):
            b = a[:l] + a[l:r+1][::-1] + a[r+1:]
            if all(b[i] <= b[i+1] for i in range(len(b)-1)):
                possible = True
    if possible:
        assert v == len(a)
    else:
        assert 1 <= v <= len(a)

def test_exact_masks(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    ans = 0
    for l in range(len(a)):
        for r in range(l, len(a)):
            b = a[:l] + a[l:r+1][::-1] + a[r+1:]
            for m in range(1 << len(b)):
                q = [b[i] for i in range(len(b)) if m >> i & 1]
                if all(q[i] <= q[i+1] for i in range(len(q)-1)):
                    ans = max(ans, len(q))
    assert v == ans

def test_exact_splits(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    ans = 0
    for l in range(len(a)):
        for r in range(l, len(a)):
            b = a[:l] + a[l:r+1][::-1] + a[r+1:]
            for t in range(len(b)+1):
                ans = max(ans, b[:t].count(1) + b[t:].count(2))
    assert v == ans

def test_exact_dp(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    ans = 0
    for l in range(len(a)):
        for r in range(l, len(a)):
            b = a[:l] + a[l:r+1][::-1] + a[r+1:]
            d = [1] * len(b)
            for i in range(len(b)):
                for j in range(i):
                    if b[j] <= b[i]: d[i] = max(d[i], d[j] + 1)
            ans = max(ans, max(d))
    assert v == ans

def test_exact_combinations(run, x):
    from itertools import combinations
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    ans = 0
    for l in range(len(a)):
        for r in range(l, len(a)):
            b = a[:l] + a[l:r+1][::-1] + a[r+1:]
            for k in range(1, len(b)+1):
                for ix in combinations(range(len(b)), k):
                    if all(b[ix[j]] <= b[ix[j+1]] for j in range(k-1)): ans = max(ans, k)
    assert v == ans

def test_exact_prefix_suffix(run, x):
    a = list(map(int, x.split()[1:]))
    try:
        v = int(run(x).strip())
    except Exception:
        assert False
    ans = 0
    for l in range(len(a)):
        for r in range(l, len(a)):
            b = a[:l] + list(reversed(a[l:r+1])) + a[r+1:]
            for cut in range(len(b)+1):
                candidate = sum(z == 1 for z in b[:cut]) + sum(z == 2 for z in b[cut:])
                if candidate > ans: ans = candidate
    assert v == ans

def test_pairwise_masks(run, x):
    import itertools
    a = list(map(int, x.split()))[1:]
    total = 0
    for m in range(1, 1 << len(a)):
        b = [a[i] for i in range(len(a)) if m >> i & 1]
        total += max(abs(u-v) for u in b for v in b)
    assert run(x).strip() == str(total % 1000000007)

def test_combination_extrema(run, x):
    import itertools
    a = list(map(int, x.split()))[1:]
    total = 0
    for k in range(1, len(a)+1):
