def test_subset_lists(run, x):
    a = list(map(int, x.split()))[1:]
    total = 0
    for m in range(1, 1 << len(a)):
        b = []
        for i, v in enumerate(a):
            if m & (1 << i):
                b.append(v)
        total += max(b) - min(b)
    assert run(x).strip() == str(total % 1000000007)

def test_binary_subsets(run, x):
    a = list(map(int, x.split()))[1:]
    total = 0
    for bits in range(1, 64):
        lo = None
        hi = None
        for i in range(6):
            if bits & (1 << i):
                lo = a[i] if lo is None or a[i] < lo else lo
                hi = a[i] if hi is None or a[i] > hi else hi
        total += hi - lo
    assert run(x).strip() == str(total % 1000000007)

def test_combinations_pairs(run, x):
