def test_mask_extrema(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for mask in range(1, 1 << n):
        chosen = [a[i] for i in range(n) if mask & (1 << i)]
        total += max(chosen) - min(chosen)
    assert int(run(x).strip()) == total % 1000000007


def test_pairwise_definition(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for mask in range(1, 1 << n):
        best = 0
        for i in range(n):
            for j in range(n):
                if mask & (1 << i) and mask & (1 << j):
                    best = max(best, abs(a[i] - a[j]))
        total += best
    assert int(run(x).strip()) == total % 1000000007


def test_combinations(run, x):
    from itertools import combinations
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for k in range(1, n + 1):
        for subset in combinations(a, k):
            total += max(subset) - min(subset)
    assert int(run(x).strip()) == total % 1000000007


def test_recursive_subsets(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    subsets = []
    def visit(i, chosen):
        if i == n:
            if chosen:
                subsets.append(chosen)
            return
        visit(i + 1, chosen)
        visit(i + 1, chosen + [a[i]])
    visit(0, [])
    total = sum(max(s) - min(s) for s in subsets)
    assert int(run(x).strip()) == total % 1000000007


def test_bit_product(run, x):
    from itertools import product
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for bits in product((0, 1), repeat=n):
        values = [a[i] for i, bit in enumerate(bits) if bit]
        if values:
            total += max(values) - min(values)
    assert int(run(x).strip()) == total % 1000000007


def test_index_combinations(run, x):
    from itertools import combinations
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for size in range(1, n + 1):
        for indices in combinations(range(n), size):
            farthest = 0
            for i in indices:
                for j in indices:
                    farthest = max(farthest, abs(a[i] - a[j]))
            total += farthest
    assert int(run(x).strip()) == total % 1000000007


def test_binary_strings(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for number in range(1, 2 ** n):
        bits = format(number, '0%db' % n)
        lo = None
        hi = None
        for i, bit in enumerate(bits):
            if bit == '1':
                lo = a[i] if lo is None else min(lo, a[i])
                hi = a[i] if hi is None else max(hi, a[i])
        total += hi - lo
    assert int(run(x).strip()) == total % 1000000007


def test_incremental_masks(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for mask in range(1, 1 << n):
        values = []
        for i in range(n):
            if (mask >> i) % 2:
                values.append(a[i])
        values.sort()
        total += values[-1] - values[0]
    assert int(run(x).strip()) == total % 1000000007


def test_subset_list(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = 0
    for mask in range(1, 1 << n):
        subset = [a[i] for i in range(n) if (mask // (1 << i)) % 2]
        distances = [abs(u - v) for u in subset for v in subset]
        total += max(distances)
    assert int(run(x).strip()) == total % 1000000007


def test_boolean_recursion(run, x):
    data = list(map(int, x.split()))
    n, a = data[0], data[1:]
    total = [0]
    def choose(pos, low, high, used):
        if pos == n:
            if used:
                total[0] += high - low
            return
        choose(pos + 1, low, high, used)
        value = a[pos]
        if used:
            choose(pos + 1, min(low, value), max(high, value), True)
        else:
            choose(pos + 1, value, value, True)
    choose(0, 0, 0, False)
    assert int(run(x).strip()) == total[0] % 1000000007

